#include <linux/cred.h>
#include <linux/errno.h>

int get_dest_keyring(struct key **_dest_keyring) {
    struct key *dest_keyring = *_dest_keyring;
    struct key *default_keyring = NULL;
    int ret = 0;

    if (dest_keyring) {
        /* Check if the provided keyring is valid and has write access */
        if (key_validate(dest_keyring) < 0) {
            ret = -EINVAL;
            goto out;
        }

        if (!key_task_permission(current_cred(), dest_keyring, KEY_LOOKUP)) {
            ret = -EACCES;
            goto out;
        }

        *_dest_keyring = dest_keyring;
        return 0;
    }

    /* Attempt to find the default keyring */
    default_keyring = find_default_keyring();
    if (!default_keyring) {
        ret = -ENOENT;
        goto out;
    }

    /* Ensure the default keyring is writable */
    if (key_validate(default_keyring) < 0) {
        ret = -EINVAL;
        goto out;
    }

    if (!key_task_permission(current_cred(), default_keyring, KEY_LOOKUP)) {
        ret = -EACCES;
        goto out;
    }

    *_dest_keyring = default_keyring;
    return 0;

