#include <linux/key.h>
#include <linux/err.h>
#include <linux/cred.h>

int get_dest_keyring(struct key **_dest_keyring) {
    struct key *dest_keyring = *_dest_keyring;
    struct key *default_keyring = NULL;
    int ret;

    if (!dest_keyring) {
        struct cred *cred = current_cred();
        default_keyring = find_keyring_by_uid(cred->uid);
        if (IS_ERR(default_keyring)) {
            return PTR_ERR(default_keyring);
        }
        dest_keyring = default_keyring;
    }

    ret = key_validate(dest_keyring);
    if (ret < 0) {
        return ret;
    }

    if (!capable(CAP_SYS_ADMIN) && !key_permission(dest_keyring, KEY_NEED_WRITE)) {
        return -EACCES;
    }

    *_dest_keyring = dest_keyring;
    return 0;
}

#include <linux/key.h>
#include <linux/errno.h>

int get_dest_keyring(struct key **_dest_keyring) {
    struct key *keyring = NULL;
    int ret = 0;

    if (!_dest_keyring)
        return -EINVAL;

    /* Check if a destination keyring is provided */
    if (*_dest_keyring) {
        keyring = *(_dest_keyring);
    } else {
        /* Attempt to find a suitable default keyring based on current credentials */
        keyring = key_for_uid(current_uid());
        if (IS_ERR(keyring))
            return PTR_ERR(keyring);
    }

    /* Perform permission checks to ensure write access */
    ret = key_permission(keyring, KEY_LOOKUP);
    if (ret < 0)
        return ret;

    /* Assign the keyring back to the destination pointer */
    *_dest_keyring = keyring;
    return 0;
}

#include <linux/key.h>
#include <linux/errno.h>

int construct_dest_keyring(struct key **_dest_keyring) {
    struct key *dest_keyring = NULL;
    int ret;

    if (_dest_keyring == NULL)
        return -EINVAL;

    if (*_dest_keyring != NULL) {
        dest_keyring = *(_dest_keyring);
    } else {
        struct cred *cred = current_cred();
        struct key *default_keyring;

        default_keyring = key_get(cred->uid);
        if (IS_ERR(default_keyring))
            return PTR_ERR(default_keyring);

        ret = key_permission(current, default_keyring, KEY_PERM_WRITE);
        if (ret) {
            key_put(default_keyring);
            return ret;
        }

        dest_keyring = default_keyring;
    }

    *(_dest_keyring) = dest_keyring;
    return 0;
}
